<?php
declare(strict_types=1);
namespace App\Controllers;
use App\Core\Auth;use App\Core\Database;use App\Core\View;use DateTimeImmutable;use Throwable;
final class InsuranceController
{
    public function index():void{$pdo=Database::connection();$q=trim($_GET['q']??'');$type=trim($_GET['holder_type']??'');$status=trim($_GET['status']??'');$sql='SELECT p.*,COALESCE(CONCAT(s.last_name,", ",s.first_name),CONCAT(t.last_name,", ",t.first_name),CONCAT(e.last_name,", ",e.first_name)) holder_name,COALESCE(s.student_no,t.employee_no,e.employee_no) reference_no,(SELECT COUNT(*) FROM insurance_claims c WHERE c.insurance_policy_id=p.id) claim_count FROM insurance_policies p LEFT JOIN students s ON s.id=p.student_id LEFT JOIN teachers t ON t.id=p.teacher_id LEFT JOIN employees e ON e.id=p.employee_id WHERE 1=1';$args=[];if($q!==''){$sql.=' AND (p.policy_no LIKE ? OR p.provider LIKE ? OR s.first_name LIKE ? OR s.last_name LIKE ? OR t.first_name LIKE ? OR t.last_name LIKE ? OR e.first_name LIKE ? OR e.last_name LIKE ?)';$like='%'.$q.'%';$args=array_fill(0,8,$like);}if(in_array($type,['student','teacher','employee'],true)){$sql.=' AND p.holder_type=?';$args[]=$type;}if(in_array($status,['pending','active','expired','cancelled'],true)){$sql.=' AND p.status=?';$args[]=$status;}$sql.=' ORDER BY p.coverage_end,p.created_at DESC LIMIT 300';$stmt=$pdo->prepare($sql);$stmt->execute($args);$policies=$stmt->fetchAll();$pdo->exec('UPDATE insurance_policies SET status="expired" WHERE status="active" AND coverage_end<CURDATE()');$summary=$pdo->query('SELECT SUM(status="active") active_count,SUM(status="active" AND coverage_end BETWEEN CURDATE() AND DATE_ADD(CURDATE(),INTERVAL 30 DAY)) expiring_count,SUM(status="expired") expired_count,(SELECT COUNT(*) FROM insurance_claims WHERE status IN ("submitted","under_review")) open_claims FROM insurance_policies')->fetch();View::render('insurance/index',compact('policies','summary','q','type','status'));}
    public function create():void{$this->renderForm([],[]);}
    public function store():void{$in=['holder_type'=>trim($_POST['holder_type']??''),'profile_id'=>(int)($_POST['profile_id']??0),'provider'=>trim($_POST['provider']??''),'policy_no'=>trim($_POST['policy_no']??''),'plan_name'=>trim($_POST['plan_name']??''),'coverage_start'=>trim($_POST['coverage_start']??''),'coverage_end'=>trim($_POST['coverage_end']??''),'premium_amount'=>trim($_POST['premium_amount']??''),'coverage_amount'=>trim($_POST['coverage_amount']??''),'status'=>trim($_POST['status']??'active'),'remarks'=>trim($_POST['remarks']??'')];$errors=[];if(!in_array($in['holder_type'],['student','teacher','employee'],true)||!$in['profile_id'])$errors[]='Choose a valid policy holder.';foreach(['provider'=>'Provider','policy_no'=>'Policy number','coverage_start'=>'Coverage start','coverage_end'=>'Coverage end'] as $k=>$label)if($in[$k]==='')$errors[]=$label.' is required.';if(!$this->date($in['coverage_start'])||!$this->date($in['coverage_end'])||$in['coverage_end']<$in['coverage_start'])$errors[]='Coverage dates are invalid.';if(!in_array($in['status'],['pending','active','expired','cancelled'],true))$errors[]='Invalid policy status.';foreach(['premium_amount','coverage_amount'] as $amount)if($in[$amount]!==''&&(!is_numeric($in[$amount])||(float)$in[$amount]<0))$errors[]='Amounts cannot be negative.';$pdo=Database::connection();$table=['student'=>'students','teacher'=>'teachers','employee'=>'employees'][$in['holder_type']]??'students';if(!$errors){$check=$pdo->prepare("SELECT id FROM {$table} WHERE id=?");$check->execute([$in['profile_id']]);if(!$check->fetch())$errors[]='The selected holder does not exist.';}if($errors){$this->renderForm($errors,$in);return;}$ids=['student_id'=>null,'teacher_id'=>null,'employee_id'=>null];$ids[$in['holder_type'].'_id']=$in['profile_id'];try{$pdo->prepare('INSERT INTO insurance_policies(holder_type,student_id,teacher_id,employee_id,provider,policy_no,plan_name,coverage_start,coverage_end,premium_amount,coverage_amount,status,remarks,created_by) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)')->execute([$in['holder_type'],$ids['student_id'],$ids['teacher_id'],$ids['employee_id'],$in['provider'],$in['policy_no'],$in['plan_name']?:null,$in['coverage_start'],$in['coverage_end'],$in['premium_amount']!==''?$in['premium_amount']:null,$in['coverage_amount']!==''?$in['coverage_amount']:null,$in['status'],$in['remarks']?:null,Auth::user()['id']]);$id=(int)$pdo->lastInsertId();Auth::audit('insurance.policy_created','insurance_policies',(string)$id,null,$in);flash('success','Insurance policy created.');Auth::redirect('/insurance/'.$id);}catch(\PDOException $e){$errors[]='Policy number is already in use or a value is invalid.';$this->renderForm($errors,$in);}}
    public function show(string $id):void{$policy=$this->find((int)$id);if(!$policy)return;$s=Database::connection()->prepare('SELECT c.*,u.display_name recorder FROM insurance_claims c JOIN users u ON u.id=c.recorded_by WHERE c.insurance_policy_id=? ORDER BY c.filed_on DESC,c.id DESC');$s->execute([$id]);View::render('insurance/show',['policy'=>$policy,'claims'=>$s->fetchAll()]);}
    public function addClaim(string $id):void{$policy=$this->find((int)$id);if(!$policy)return;$claimNo=trim($_POST['claim_no']??'');$filed=trim($_POST['filed_on']??'');$incident=trim($_POST['incident_date']??'');$amount=(float)($_POST['claim_amount']??0);if($claimNo===''||!$this->date($filed)||($incident!==''&&!$this->date($incident))||$amount<=0){flash('error','Enter a claim number, valid dates, and an amount greater than zero.');Auth::redirect('/insurance/'.$id);}try{Database::connection()->prepare('INSERT INTO insurance_claims(insurance_policy_id,claim_no,filed_on,incident_date,claim_amount,remarks,recorded_by) VALUES(?,?,?,?,?,?,?)')->execute([(int)$id,$claimNo,$filed,$incident?:null,number_format($amount,2,'.',''),substr(trim($_POST['remarks']??''),0,1000)?:null,Auth::user()['id']]);$claimId=(string)Database::connection()->lastInsertId();Auth::audit('insurance.claim_created','insurance_claims',$claimId,null,['policy_id'=>(int)$id,'claim_no'=>$claimNo]);flash('success','Insurance claim recorded.');}catch(\PDOException $e){flash('error','Claim number is already in use.');}Auth::redirect('/insurance/'.$id);}
    public function updateClaim(string $id,string $claimId):void{$policy=$this->find((int)$id);if(!$policy)return;$status=$_POST['status']??'';$approved=trim($_POST['approved_amount']??'');if(!in_array($status,['submitted','under_review','approved','rejected','paid'],true)||($approved!==''&&(!is_numeric($approved)||(float)$approved<0))){flash('error','Claim status or approved amount is invalid.');Auth::redirect('/insurance/'.$id);}$s=Database::connection()->prepare('UPDATE insurance_claims SET status=?,approved_amount=? WHERE id=? AND insurance_policy_id=?');$s->execute([$status,$approved!==''?$approved:null,(int)$claimId,(int)$id]);Auth::audit('insurance.claim_updated','insurance_claims',$claimId,null,['status'=>$status,'approved_amount'=>$approved]);flash('success','Claim updated.');Auth::redirect('/insurance/'.$id);}
    public function updateStatus(string $id):void{$policy=$this->find((int)$id);if(!$policy)return;$status=$_POST['status']??'';if(!in_array($status,['pending','active','expired','cancelled'],true)){flash('error','Invalid policy status.');Auth::redirect('/insurance/'.$id);}Database::connection()->prepare('UPDATE insurance_policies SET status=? WHERE id=?')->execute([$status,(int)$id]);Auth::audit('insurance.policy_status_updated','insurance_policies',$id,null,['status'=>$status]);flash('success','Policy status updated.');Auth::redirect('/insurance/'.$id);}
    private function renderForm(array $errors,array $input):void{$pdo=Database::connection();View::render('insurance/form',['errors'=>$errors,'input'=>$input,'students'=>$pdo->query('SELECT id,student_no,first_name,last_name FROM students WHERE student_status="active" ORDER BY last_name,first_name')->fetchAll(),'teachers'=>$pdo->query('SELECT id,employee_no,first_name,last_name FROM teachers WHERE employment_status="active" ORDER BY last_name,first_name')->fetchAll(),'employees'=>$pdo->query('SELECT id,employee_no,first_name,last_name FROM employees WHERE employment_status="active" ORDER BY last_name,first_name')->fetchAll()]);}
    private function find(int $id):?array{$s=Database::connection()->prepare('SELECT p.*,COALESCE(CONCAT(st.first_name," ",st.last_name),CONCAT(t.first_name," ",t.last_name),CONCAT(e.first_name," ",e.last_name)) holder_name,COALESCE(st.student_no,t.employee_no,e.employee_no) reference_no FROM insurance_policies p LEFT JOIN students st ON st.id=p.student_id LEFT JOIN teachers t ON t.id=p.teacher_id LEFT JOIN employees e ON e.id=p.employee_id WHERE p.id=?');$s->execute([$id]);$p=$s->fetch();if(!$p){http_response_code(404);View::render('errors/message',['title'=>'Policy not found','message'=>'The requested insurance policy does not exist.']);return null;}return$p;}
    private function date(string $value):bool{$d=DateTimeImmutable::createFromFormat('Y-m-d',$value);return$d&&$d->format('Y-m-d')===$value;}
}
